-- Morning and Evening
update public.devotional_plans
set description = 'The full public-domain daily edition of Charles Spurgeon''s classic devotional, stored with both the morning and evening readings together in each day entry.',
    total_days = 366,
    updated_at = '2026-04-14 20:15:00+00'
